export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:10。M 區。系統安全組工作站。螢幕上打開了一張圖。不是依存圖。不是閉環圖。是一條時間軸。軸上標著六個條件閘門。每個閘門旁邊寫著一行字。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部站在螢幕旁邊。他的聲音回到了程序模式。像在讀一份結構化報告。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "R4 失敗包絡。技術模型判定——只有在以下最小失敗條件全部成立時，R4 才會成為可能未來中可理解的候選。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他指向第一個閘門。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件一。缺失原始簽署載體已重新授權。OFFLINE_LOCAL_AUTH 被啟用。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二個閘門。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件二。emergency override 已啟用。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三個。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件三。CONSENSUS COMMIT 進入不可逆前段。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第四個。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件四。B 家族的延後提交或阻止提交已失敗。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第五個。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件五。VALIDATION COHORT 中多人獨立陳述同一不存在事件。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第六個。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "條件六。距 public fanout 只剩極短時間。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他放下手。看著所有人。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這六個條件是模型條件。不是已知歷史。當輪沒有證據顯示公共異常已經發生。VALIDATION COHORT 的異常一致化是 R4 形成的前提——不是已經被觀測到的事實。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家在鍵盤上操作。螢幕上的圖放大了。六個閘門之間用箭頭連著。每個箭頭上標著因果方向。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "VALIDATION COHORT。一致性層正式 fanout 前的小型驗證群組。用途——驗證提示是否產生共同理解。由少量授權操作員、測試帳號或受控參與者接收預覽。不等於真正公眾輸出。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "在失敗包絡中——COHORT 成員開始獨立陳述同一件不存在的事件。不是被引導。不是被告知。是各自描述出相同的內容。這代表一致性層的提示已經開始在封閉群組內產生異常一致化。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "此時公共異常已超過純理論。卻仍未全面擴散。R4 因此成為技術上可理解、倫理上仍有問題的候選。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:20。千田走到螢幕前。他在時間軸上標了兩條路線。A。B。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "A 家族。完整安全切離。為什麼在可能未來中失敗。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在 A 路線上寫了四個瓶頸。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "瓶頸一。身分與位置缺口。部分活動接收者的身分、位置與法人仍未確認。無法對未確認的人建立本地影子參照。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "瓶頸二。個別影子參照生成。每個人的影子參照必須個別生成。不能直接複製。生成需要時間。需要醫療評估。需要設備。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "瓶頸三。缺少完整回聲窗演練。高負荷真正出現在回聲窗附近。平時測試不足以證明星期一的安全。沒有在真實高負荷條件下完成過一次完整的安全交接。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "瓶頸四。缺失載體可能覆蓋安全配置。即使 A 家族完成了所有步驟——缺失載體持有 OFFLINE_LOCAL_AUTH 權限。可以在最後階段重新授權。覆蓋已建立的安全配置。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他放下筆。看著那四個瓶頸。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "在可能未來中——這四個瓶頸同時成立。A 家族在星期一前無法完成。不是因為某一個環節失敗。是因為四個瓶頸疊加。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:30。他轉向 B 路線。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "B 家族。保留過濾。延後或阻止提交。凍結 commit。保留 M-00 原始過濾。禁用 public route。延長 CAL LOCK。將提交推遲到回聲窗後。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在 B 路線上畫了一個叉。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "B 家族在可能未來中的失敗——缺失載體重新授權後，遠端凍結不足。emergency override 恢復後，本地狀態被改寫。一旦 commit 進入不可逆前段——B 家族失效。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著澪。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "B 家族不需要硬切。不需要切斷閉環。但它的前提是——本地狀態不被改寫。在失敗包絡中，這個前提不成立。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）A 來不及。B 擋不住。到那個時點——只剩 C。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上那條時間軸的箭頭還亮著。六個閘門。兩條路線。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）只剩硬切。只剩切斷閉環。這就是未來的我面對的。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的指甲掐進掌心。沒有出血。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不是在好方案裡選一個。是在所有方案都失敗以後——只剩一個會傷害人的方案。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:40。日下部把四個紅區的封存摘要調出來。螢幕上。四行代碼。M-00。G07／03。高依存遠端單元 B。LEGACY／02。每行後面標著——紅區。HUMAN。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "四個紅區。在所有合理參數組合中——均跨越不可逆嚴重傷害門檻。部分情境包含死亡。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的聲音很平。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不寫死亡數。不寫「一定死」。不寫「四個人會死」。寫——在所有合理情境中，以上四名活動接收者均跨越不可逆嚴重傷害門檻。部分情境包含死亡。其他活動單元亦有風險，但無法建立同樣穩定的下限。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著那四行。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這是 R4 的代價下限。不是上限。不是精確預測。是——無論參數怎麼調整，這四個人都會被寫進去。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:50。走廊裡安靜了。不是沒有人說話。是沒有人知道該說什麼。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師翻開他的夾板。他沒有看 R4 候選。他只看他的醫療評估。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "M-00。高度依賴雙向閉環。硬切可能造成死亡、深度昏迷或不可逆神經崩潰。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "G07／03。13.4 秒自然故障時呼吸、自律與腦電嚴重波動。本地影子參照不完整。硬切風險不可接受。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "高依存遠端單元 B。歷史切換時長時間癲癇樣放電。無完整本地影子參照。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "LEGACY／02。唯一穩定源仍為 M-00。本地模型已退役。過去失去參照後長時間失語及意識障礙。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他合上夾板。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "四名。均為活人。均為 HUMAN。中斷風險不可接受。這是外部醫療組的獨立結論。與系統組一致。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:00。凪原從牆邊走過來。她的步伐很穩。她走到螢幕前。她看著那六個條件閘門。她看著 A 路線的四個瓶頸。她看著 B 路線的叉。她看著四個紅區。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的臉沒有變。但她的眼睛在四個紅區上停了比平常更長的時間。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "失敗包絡成立時——CONSENSUS COMMIT 已進入不可逆前段。VALIDATION COHORT 已開始異常一致化。距 public fanout 只剩極短時間。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。她的聲音和往常一樣——學術。精確。不帶情緒。但她的語速慢了一拍。只有一拍。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "到那個時點，妳會只剩幾秒。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著澪。不是看著白板。不是看著螢幕。是看著澪。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡沒有聲音。所有人都聽到了那句話。不是「妳會有時間選擇」。不是「妳可以慢慢決定」。是——只剩幾秒。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著她。凪原的臉沒有變。銀框眼鏡。白袍。但她的眼睛是清醒的。不是冷漠。是清醒。她在說一個她見過的時點。不是理論。是經驗。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）幾秒。她說的是函館。十年前。十七個人同時昏迷。軍事雷達誤判。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原的眼睛沒有移開。她看著澪。不是看著白板。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她經歷過那個時點。她知道「只剩幾秒」是什麼感覺。她不是在嚇我。她是在告訴我——那個時點真的存在。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡沒有聲音。連呼吸器的節奏都像被壓低了。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她從那個時點走出來。然後用十年把自己變成不會再讓那個時點發生的人。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪的手指在膝蓋上收緊。又鬆開。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）可是她變成的方式——是把人變成代碼。是把紗英維持成 M-00。她從「只剩幾秒」裡學到的——是控制。不是撤離。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:05。澪站起來。她的膝蓋還是有點僵。但她站直了。她看著凪原。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "所以我們現在不能把自己安排到只剩那幾秒。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音不高。但很清楚。每一個字都像在釘釘子。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "A 家族的瓶頸是真的。B 家族的弱點是真的。失敗包絡是可能的。這些我都不否認。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "但「可能未來中的我會只剩幾秒」——不能變成「我們現在就預先接受只剩幾秒」。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "如果現在就接受——就等於現在就把那四個人寫進代價。就等於現在就關閉姓名欄。就等於現在就讓 R4 變成預設方案。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原沒有回應。她的臉沒有變。但她也沒有重複「只剩幾秒」。她站在那裡。像在衡量什麼。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:10。千田在白板上補了一行。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "R4 的失敗包絡是模型條件。不是當輪歷史。當輪缺失載體尚未重新授權。emergency override 尚未啟用。CONSENSUS COMMIT 仍為 PENDING。VALIDATION COHORT 異常尚未被觀測。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他放下筆。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "失敗包絡告訴我們——R4 在可能未來中為什麼會被選擇。它不告訴我們——現在必須選擇 R4。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家在鍵盤上操作。螢幕上的圖縮小了。六個條件閘門。兩條路線。四個紅區。全部在一張圖裡。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "R4 失敗包絡重建完成。技術上——R4 是在 A 路線無法及時完成、B 路線被覆蓋、commit 逼近、公共異常開始一致化時——唯一能高概率阻止 fanout 的候選。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "它的代價是——四個紅區。四個活人。包括 M-00。包括未成年人。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "這是 R4 為什麼會被選擇的技術原因。不是 R4 應該被選擇的倫理理由。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:20。走廊裡的人開始整理。封存。編號。簽名。時間戳。失敗包絡圖被拍下來。封存。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在走廊盡頭。她沒有站著。她坐下了。她的手放在膝蓋上。她看著螢幕上那張縮小的圖。六個閘門。兩條路線。四個紅區。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）幾秒。她說的對。到那個時點——只剩幾秒。A 來不及。B 擋不住。C 會傷人。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕的光映在她臉上。沒有變。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）沒有好方案。未來的我面對的就是這個。沒有好方案。只剩不那麼壞的方案。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的背靠著牆。涼的。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她選了 C。她接受了代價。一次。然後她要求不要把方案送回來。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊那端有人合上筆電。扣鎖的聲音很輕。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）因為她知道——如果送回來——現在的我可能會直接用它。可能會在還沒有走到只剩幾秒的時候——就先用它。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的眼睛沒有閉。她看著那四個代碼。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她把方案堵在門外。只留下拒絕的理由。不是因為方案不對。是因為——如果方案太容易拿到——人就會在還有時間的時候先放棄那些人。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:30。日下部走到澪面前。他遞了一杯水。澪接過來。喝了一口。水是涼的。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "失敗包絡成立。技術壓力成立。R4 在可能未來中可理解。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "但——當輪還沒有走到那個時點。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "下一步。妳要什麼。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著他。他的臉很疲憊。眼下的陰影很深。但他的眼睛是清醒的。他在等她。不是等她回答。是等她要求。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "把名字補回去。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:35。走廊。螢光燈。螢幕上的圖還在。六個閘門。兩條路線。四個紅區。四個代碼。沒有名字。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原站在牆邊。她的手在口袋裡。她聽到了「把名字補回去」。她的臉沒有變。但她的下巴收了一點。只有一點。像在準備接住什麼。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "16:50。日下部開始聯絡外部人員。公共營運方。外部醫療主管。警方。司法。TKS。兒少。主管機關。臨時共同安全會議。十七點十分開始。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在走廊盡頭。她沒有動。她的手放在膝蓋上。她看著螢幕上那四個代碼。沒有名字。沒有年齡。沒有 HUMAN。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）把名字補回去。不是要求看見所有人的隱私。是要求——做決定的人至少看得到人。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的指尖壓著膝蓋。沒有握拳。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）看得到 HUMAN。看得到成年人或未成年人。看得到母親。看不到人的決定——不算決定。那只是參數調整。", background: Background.Chapter_22_Ch22_Act5_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "17:05。走廊裡開始有新的腳步聲。外部人員到了。摺疊桌被重新排開。", background: Background.Chapter_22_Ch22_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約三日十三小時八分鐘。", background: Background.Chapter_22_Ch22_Act5_S0 },
];
